import {escapeHtml as e} from '../shared/utils.js?v=0.15.0';
import {sourceDetails} from '../shared/ancestry-ui.js?v=0.15.0';
import {FIT, LABELS, fitSummary, checkChanged} from './adaptations.js?v=0.15.0';
export const fitText=(work,a)=>{const f=fitSummary(work,a);return [`${f.unresolved} unresolved`,`${f.needsChange} need change/permission`,f.unexplained?`${f.unexplained} without reasoning`:'',f.changed.length?`${f.changed.length} changed since review`:'',f.missing.length?`${f.missing.length} new limits unchecked`:'',f.removed?`${f.removed} earlier limits removed from board`:''].filter(Boolean).join(' · ');};
const field=(a,key,prompt='')=>`<div class="field"><label for="adapt-${key}">${e(LABELS[key])}</label>${prompt?`<p>${e(prompt)}</p>`:''}<textarea id="adapt-${key}" maxlength="20000" rows="2" data-edit="adapt-edit" data-id="${e(a.id)}" data-field="${key}">${e(a[key])}</textarea></div>`;
function reviewMarkup(work,a,c){const current=work.cards.find(x=>x.id===c.cardId),changed=checkChanged(work,c);return !current?'<p class="fit-alert">Removed from the board. This earlier check is retained.</p>':changed?`<div class="fit-alert"><b>Constraint changed since review</b><p>Now: ${e(current.text)} (${e(current.type)})</p><p>${e(current.basis)}</p><button class="text-button" data-action="fit-review" data-id="${e(a.id)}" data-card-id="${e(c.cardId)}">Review current wording</button><p>This returns the judgement to Unresolved and keeps the original source.</p></div>`:'';}
function fitCard(work,a,c){
 const current=work.cards.find(x=>x.id===c.cardId),changed=checkChanged(work,c);
 return `<article class="fit-card" data-drag-id="${e(c.cardId)}"><header><span class="type">${e(c.reviewed.type)}</span><button id="fit-handle-${e(c.cardId)}" class="drag-handle" data-drag-handle data-action="fit-focus" data-card-id="${e(c.cardId)}" aria-label="Move fit judgement: ${e(c.reviewed.text||'Unnamed constraint')}">⠿</button></header><p class="fit-statement">${e(c.reviewed.text||'Unnamed constraint')}</p>${c.reviewed.basis?`<details><summary>Basis</summary><p>${e(c.reviewed.basis)}</p></details>`:''}<div data-fit-review="${e(c.cardId)}">${reviewMarkup(work,a,c)}</div><label for="fit-status-${e(c.cardId)}">Your judgement</label><select id="fit-status-${e(c.cardId)}" data-edit="adapt-check" data-id="${e(a.id)}" data-card-id="${e(c.cardId)}" data-field="status">${Object.entries(FIT).map(([key,label])=>`<option value="${key}" ${c.status===key?'selected':''}>${label}</option>`).join('')}</select><details id="fit-reason-${e(c.cardId)}"><summary>Reasoning ${c.explanation.trim()?'recorded':'to write'}</summary><div class="field"><label for="fit-note-${e(c.cardId)}">Why / what must change?</label><textarea id="fit-note-${e(c.cardId)}" data-edit="adapt-check" data-id="${e(a.id)}" data-card-id="${e(c.cardId)}" data-field="explanation" maxlength="20000" rows="2">${e(c.explanation)}</textarea></div></details></article>`;
}
function editor(work,a){
 const f=fitSummary(work,a);
 return `<section id="adaptation-editor" class="adaptation-editor" aria-label="Develop adaptation"><header class="adaptation-heading"><div><p class="eyebrow">MAKE IT WORK IN REALITY</p><h3>${a.ancestry.parked?'Parked adaptation':'Develop this alternative'}</h3></div><div class="toolbar"><button class="button" data-action="adapt-branch" data-id="${e(a.id)}">Branch a variation</button><button class="button" data-action="adapt-park" data-id="${e(a.id)}">${a.ancestry.parked?'Revive':'Park'}</button><button class="text-button" data-action="adapt-remove" data-id="${e(a.id)}">Remove</button></div></header>${sourceDetails(a.ancestry)}<div class="adaptation-writing"><div>${field(a,'title')}${field(a,'mechanism','Describe the actual behaviour, design or sequence.')}</div><div>${field(a,'kept','Which principle from the thought experiment still helps?')}${field(a,'leftBehind','Which imaginary assumption does the real version give up?')}</div></div>${a.ancestry.parents.some(p=>p.fields.some(f=>f.label==='How it would work'))?`<details id="branch-reason" open><summary>What changes and why?</summary><div class="adaptation-writing">${field(a,'changed')}${field(a,'reason')}</div></details>`:''}
 <div class="fit-intro"><div><h3>Try it against the real limits</h3><p>Drag a judgement into another column, or use its selector. Record why it fits, what must change, or what remains unknown.</p><p class="microcopy">These are your judgements, not verified feasibility. Physical limits require a different design or corrected evidence; moving a card does not grant permission.</p></div>${f.missing.length?`<button class="button" data-action="adapt-sync" data-id="${e(a.id)}">Add ${f.missing.length} new constraint${f.missing.length===1?'':'s'} to check</button>`:''}</div>
 <div id="fit-board" class="fit-scroll" tabindex="0" role="region" aria-label="Constraint fit board; scroll sideways"><div class="fit-board">${Object.entries(FIT).map(([key,label])=>`<section class="fit-lane fit-${key}" data-drop-id="${key}" aria-label="${label}"><h4>${label} <span>${a.checks.filter(c=>c.status===key).length}</span></h4>${a.checks.filter(c=>c.status===key).map(c=>fitCard(work,a,c)).join('')||'<p class="empty-zone">Move a judgement here.</p>'}</section>`).join('')}</div></div><p class="fit-scroll-hint">Scroll sideways to compare the three columns ↔</p>
 <details id="adaptation-test" open><summary>A bounded test</summary><div class="adaptation-writing"><div>${field(a,'test','Who tries what, for how long, and what stays protected?')}${field(a,'permission')}</div>${field(a,'evidence','An observation that would make you revise or stop.')}</div></details></section>`;
}
function compare(work){
 const items=work.compareIds.map(id=>work.adaptations.find(a=>a.id===id));if(!items.length)return '<p class="empty-zone">Choose up to four adaptations to compare.</p>';
 const rows=[['Mechanism','mechanism'],['Principle kept','kept'],['Imaginary assumption left behind','leftBehind'],['Fit review','fit'],['Smallest test','test'],['Agreement needed','permission'],['Revise or stop if','evidence']];
 return `<div class="adaptation-table-scroll" tabindex="0" role="region" aria-label="Compare adaptations; scroll sideways"><table class="adaptation-table"><thead><tr><th scope="col">Compare</th>${items.map(a=>`<th scope="col"><button class="text-button" data-action="adapt-select" data-id="${e(a.id)}">${e(a.title||'Untitled adaptation')}</button><button class="button ${work.chosenId===a.id?'primary':''}" data-action="adapt-choose" data-id="${e(a.id)}" aria-pressed="${work.chosenId===a.id}">${work.chosenId===a.id?'Chosen test':'Choose this test'}</button></th>`).join('')}</tr></thead><tbody>${rows.map(([label,key])=>`<tr><th scope="row">${label}</th>${items.map(a=>`<td data-compare-id="${e(a.id)}" data-compare-field="${key}">${e((key==='fit'?fitText(work,a):a[key])||'Not written.')}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
}
export function adaptationsPanel(work){
 const selected=work.adaptations.find(a=>a.id===work.selectedAdaptationId);
 const cards=items=>items.map(a=>`<article class="adaptation-card ${a.id===work.selectedAdaptationId?'selected':''}"><button class="card-text" data-action="adapt-select" data-id="${e(a.id)}" aria-pressed="${a.id===work.selectedAdaptationId}">${e(a.title||'Untitled adaptation')}</button><p data-mechanism="${e(a.id)}">${e(a.mechanism||'Mechanism to develop.')}</p><p class="microcopy" data-fit-summary="${e(a.id)}">${e(fitText(work,a))}</p>${!a.ancestry.parked?`<label class="compare-check"><input type="checkbox" data-action="adapt-compare" data-id="${e(a.id)}" ${work.compareIds.includes(a.id)?'checked':''}> Compare</label>`:'<span class="type">Parked</span>'}${work.chosenId===a.id?'<p class="chosen-label">Chosen test</p>':''}</article>`).join('');
 return `<section class="adaptations" id="adaptations" aria-labelledby="adaptations-title"><header class="adaptation-heading"><div><p class="eyebrow">RETURN TO REALITY</p><h2 id="adaptations-title">Keep several ways forward</h2></div>${work.adaptations.length?'<button class="button" data-action="adapt-family">Follow branches</button>':''}</header><p>Restore a constraint, then develop an adaptation from its notebook. Each keeps the source wording and its own fit judgements.</p>${work.adaptations.length?`<div class="adaptation-collection">${cards(work.adaptations.filter(a=>!a.ancestry.parked))}</div>${work.adaptations.some(a=>a.ancestry.parked)?`<details id="parked-adaptations"><summary>Parked alternatives</summary><div class="adaptation-collection">${cards(work.adaptations.filter(a=>a.ancestry.parked))}</div></details>`:''}${selected?editor(work,selected):''}<section class="adaptation-comparison" id="adaptation-comparison"><h3>Which test is worth trying?</h3><p>Compare mechanisms and remaining questions. Choosing a test does not resolve its open constraints.</p>${compare(work)}<div class="field"><label for="adapt-decision">Why this test, and what remains unresolved?</label><textarea id="adapt-decision" data-edit="adapt-decision" maxlength="20000" rows="2">${e(work.decision)}</textarea></div></section>`:'<p class="empty-zone">No adaptations yet. The original experiment notes remain in the notebook above.</p>'}</section>`;
}

export function refreshAdaptations(root,work){
 const selected=work.adaptations.find(a=>a.id===work.selectedAdaptationId);
 if(selected)root.querySelectorAll('[data-fit-review]').forEach(el=>{const c=selected.checks.find(c=>c.cardId===el.dataset.fitReview);if(c)el.innerHTML=reviewMarkup(work,selected,c);});
 for(const a of work.adaptations){
  root.querySelectorAll('[data-action="adapt-select"]').forEach(el=>{if(el.dataset.id===a.id)el.textContent=a.title||'Untitled adaptation';});
  root.querySelectorAll('[data-mechanism]').forEach(el=>{if(el.dataset.mechanism===a.id)el.textContent=a.mechanism||'Mechanism to develop.';});
  root.querySelectorAll('[data-fit-summary]').forEach(el=>{if(el.dataset.fitSummary===a.id)el.textContent=fitText(work,a);});
  root.querySelectorAll('[data-compare-id]').forEach(el=>{if(el.dataset.compareId===a.id)el.textContent=(el.dataset.compareField==='fit'?fitText(work,a):a[el.dataset.compareField])||'Not written.';});
 }
}
